WITH base AS (WITH raw AS (SELECT history_id source_record_id,execution_id,process_definition_id,activity_id,start_time timestamp,actor_code actor,related_refs_json object_refs,'wf_activity_history' source_table FROM wf_activity_history WHERE lifecycle_code='COMPLETE' UNION ALL SELECT task_id,execution_id,process_definition_id,activity_id,end_time,assignee_code,related_refs_json,'wf_task_history' FROM wf_task_history WHERE delete_reason IS NULL AND outcome_code IS NOT NULL UNION ALL SELECT delivery_id,execution_id,process_definition_id,activity_id,delivered_at,actor_code,related_refs_json,'wf_message_delivery' FROM wf_message_delivery WHERE result_code='CORRELATED' UNION ALL SELECT submission_id,execution_id,process_definition_id,activity_id,submitted_at,submitted_by,related_refs_json,'wf_form_submission' FROM wf_form_submission UNION ALL SELECT external_task_id,execution_id,process_definition_id,activity_id,completed_at,worker_code,related_refs_json,'wf_external_task' FROM wf_external_task WHERE state_code='COMPLETED' AND error_code IS NULL), scoped AS (SELECT raw.*,m.semantic_code,(SELECT v.value_text FROM wf_variable_history v WHERE v.execution_id=raw.execution_id AND v.name='application_ref' AND v.created_at<=raw.timestamp ORDER BY v.revision_no DESC LIMIT 1) case_id FROM raw JOIN wf_definition_metadata m USING(process_definition_id,activity_id)), mapped AS (SELECT *,CASE semantic_code WHEN 'PF001' THEN 'Pre-Application Opened' WHEN 'PF002' THEN 'Applicant Identity Verified' WHEN 'PF003' THEN 'Parcel Linked' WHEN 'PF004' THEN 'Application Drafted' WHEN 'PF005' THEN 'Application Submitted' WHEN 'PF006' THEN 'Submission Withdrawn' WHEN 'PF007' THEN 'Application Reopened' WHEN 'PF008' THEN 'Fee Calculated' WHEN 'PF009' THEN 'Fee Invoice Issued' WHEN 'PF010' THEN 'Fee Paid' WHEN 'PF011' THEN 'Completeness Review Started' WHEN 'PF012' THEN 'Additional Information Requested' WHEN 'PF013' THEN 'Additional Documents Submitted' WHEN 'PF014' THEN 'Completeness Accepted' WHEN 'PF015' THEN 'Completeness Rejected' WHEN 'PF016' THEN 'Zoning Review Started' WHEN 'PF017' THEN 'Zoning Approved' WHEN 'PF018' THEN 'Zoning Denied' WHEN 'PF019' THEN 'Heritage Review Requested' WHEN 'PF020' THEN 'Heritage Approved' WHEN 'PF021' THEN 'Heritage Conditions Imposed' WHEN 'PF022' THEN 'Environmental Review Started' WHEN 'PF023' THEN 'Environmental Review Passed' WHEN 'PF024' THEN 'Environmental Review Failed' WHEN 'PF025' THEN 'Public Notice Published' WHEN 'PF026' THEN 'Consultation Opened' WHEN 'PF027' THEN 'Objection Filed' WHEN 'PF028' THEN 'Objection Withdrawn' WHEN 'PF029' THEN 'Consultation Closed' WHEN 'PF030' THEN 'Hearing Scheduled' WHEN 'PF031' THEN 'Hearing Held' WHEN 'PF032' THEN 'Plan Revision Requested' WHEN 'PF033' THEN 'Plan Revision Submitted' WHEN 'PF034' THEN 'Plan Revision Accepted' WHEN 'PF035' THEN 'Fire Safety Review Started' WHEN 'PF036' THEN 'Fire Safety Passed' WHEN 'PF037' THEN 'Fire Safety Failed' WHEN 'PF038' THEN 'Structural Review Started' WHEN 'PF039' THEN 'Structural Review Passed' WHEN 'PF040' THEN 'Structural Review Failed' WHEN 'PF041' THEN 'Permit Drafted' WHEN 'PF042' THEN 'Permit Approved' WHEN 'PF043' THEN 'Permit Issued' WHEN 'PF044' THEN 'Permit Amended' WHEN 'PF045' THEN 'Permit Suspended' WHEN 'PF046' THEN 'Permit Revoked' WHEN 'PF047' THEN 'Contractor Registered' WHEN 'PF048' THEN 'Work Commencement Notified' WHEN 'PF049' THEN 'Inspection Requested' WHEN 'PF050' THEN 'Inspection Scheduled' WHEN 'PF051' THEN 'Inspection Performed' WHEN 'PF052' THEN 'Inspection Passed' WHEN 'PF053' THEN 'Inspection Failed' WHEN 'PF054' THEN 'Reinspection Requested' WHEN 'PF055' THEN 'Violation Opened' WHEN 'PF056' THEN 'Violation Remediated' WHEN 'PF057' THEN 'Completion Certificate Requested' WHEN 'PF058' THEN 'Completion Certificate Issued' WHEN 'PF059' THEN 'Appeal Filed' WHEN 'PF060' THEN 'Appeal Hearing Held' WHEN 'PF061' THEN 'Appeal Allowed' WHEN 'PF062' THEN 'Appeal Dismissed' WHEN 'PF063' THEN 'Case Archived' END activity FROM scoped) SELECT case_id,activity,timestamp,source_table,source_record_id,actor,object_refs FROM mapped WHERE activity IS NOT NULL ORDER BY case_id,timestamp,source_record_id), expanded AS (SELECT j.value case_id,base.activity,base.timestamp,base.source_table,base.source_record_id,base.actor,base.object_refs,base.case_id primary_case_id FROM base,json_each(base.object_refs) j WHERE j.value GLOB 'PF-INSPECTION-*') SELECT * FROM expanded ORDER BY case_id,timestamp,source_record_id;
